import { util } from '@aws-appsync/utils';

// Queries TypeDateIndex (ItemType/SK) instead of scanning the whole
// EventSourcingTable, then applies the same RBAC rule the live listCalls
// pipeline uses: visible if Owner == me, or SharedWith contains me, or
// (ProjectId is one of myProjectIds and me is not in ExcludedUsers), or
// caller is in the Admin group. myProjectIds is stashed by GetUserProjectsJS,
// which runs earlier in this pipeline.
//
// OPTIONAL `projectId` ARGUMENT (added 2026-10-06)
// Omitted -> behaviour is byte-identical to before.
// Supplied -> the result is narrowed to that one project.
// It is applied AFTER the access rule, never inside it, so it can only ever
// SHRINK what the caller was already entitled to see. Asking for a project you
// are not a member of therefore returns an empty list, not someone else's
// meetings. The response shape is unchanged either way.
export function request(ctx) {
  const { startDateTime, endDateTime, limit, nextToken } = ctx.arguments;
  const lo = `ts#${startDateTime}`;
  const hi = `ts#${endDateTime}#~`;
  return {
    operation: 'Query',
    index: 'TypeDateIndex',
    query: {
      expression: '#it = :itemType AND #sk BETWEEN :lo AND :hi',
      expressionNames: { '#it': 'ItemType', '#sk': 'SK' },
      expressionValues: util.dynamodb.toMapValues({
        ':itemType': 'call',
        ':lo': lo,
        ':hi': hi,
      }),
    },
    scanIndexForward: false,
    limit: limit ? limit : 100,
    nextToken: nextToken ? nextToken : null,
  };
}

export function response(ctx) {
  const me = ctx.identity.username;
  const groups = ctx.identity.groups ? ctx.identity.groups : [];
  const isAdmin = groups.includes('Admin');
  const items = ctx.result.items ? ctx.result.items : [];

  // Null when the caller did not ask for a project -> the block below is skipped.
  const projectId = ctx.arguments.projectId ? ctx.arguments.projectId : null;

  let visible;
  if (isAdmin) {
    visible = items;
  } else {
    const myProjects = ctx.stash.myProjectIds ? ctx.stash.myProjectIds : [];
    visible = items.filter((item) => {
      const sharedWith = typeof item.SharedWith === 'string' ? item.SharedWith : '';
      const excluded = item.ExcludedUsers ? item.ExcludedUsers : [];
      const inShared = sharedWith.includes(me);
      const inProject = item.ProjectId && myProjects.includes(item.ProjectId) && !excluded.includes(me);
      return item.Owner === me || inShared || inProject;
    });
  }

  // Narrowing only. Runs on what survived the access rule above, so it cannot
  // grant anything. Applies to Admins too, so the argument means the same thing
  // for everyone.
  if (projectId) {
    visible = visible.filter((item) => item.ProjectId === projectId);
  }

  return { Calls: visible, nextToken: ctx.result.nextToken ? ctx.result.nextToken : null };
}
